# pretool.sh gates a push in the repo it pushes (cd, -C, --git-dir), not the session's cwd (#30)
hook() { hook_json Bash "$1" "$2" | bash "$ORCA_SRC/hooks/pretool.sh" 2>/dev/null; echo $?; }
r=$(new_repo); d=$(dirname "$r")
git -C "$r" worktree add -q -b fresh "$d/fresh"; git -C "$r" worktree add -q -b stale "$d/stale"; git -C "$r" worktree add -q -b spaced "$d/fresh wt"
for w in "$r" "$d/fresh" "$d/stale" "$d/fresh wt"; do (cd "$w" && orca-lc gate >/dev/null); done
echo edit >> "$r/README"; echo edit >> "$d/stale/README"   # main checkout and stale: marker no longer matches
plain=$(mktemp -d); git init -q "$plain/p"                 # a repo without .orca/config.json

assert_eq "$(hook "$r" 'git push')" 2 "plain push from a stale cwd"
assert_eq "$(hook "$r" $'cat > notes <<EOF\ngit push origin main\nEOF' | tail -1)" 0 "a heredoc body line is not a push"
assert_eq "$(hook "$r" $'cat > notes <<EOF\nEOF\ngit push' | tail -1)" 2 "a push after the heredoc terminator is gated"
assert_eq "$(hook "$r" $'n=$((1<<3))\ngit push origin main' | tail -1)" 2 "arithmetic << is no heredoc: the push after it is gated"
assert_eq "$(hook "$r" $'((x<<=2))\ngit push' | tail -1)" 2 "(( << )) is no heredoc either"
assert_eq "$(hook "$r" $'echo $[x<<y]\ngit push origin main' | tail -1)" 2 "\$[ << ] arithmetic is no heredoc"
assert_eq "$(hook "$r" $'git status # see <<EOF\ngit push origin main' | tail -1)" 2 "<< in a comment is no heredoc"
assert_eq "$(hook "$r" $'ls # a<<b\ngit push' | tail -1)" 2 "<< in a comment after a word is no heredoc"
assert_eq "$(hook "$r" $'# don\'t forget\ngit push' | tail -1)" 2 "a quote in a comment opens nothing"
assert_eq "$(hook "$r" 'echo a#b; git push' | tail -1)" 2 "# inside a word is no comment"
assert_eq "$(hook "$r" 'echo ${x:- #y}; git push' | tail -1)" 2 "# after a space inside \${ } is no comment"
assert_eq "$(hook "$r" 'echo ${x/ #/}; git push' | tail -1)" 2 "# in a \${ } pattern is no comment"
assert_eq "$(hook "$r" 'a=${b:-x #}; git push' | tail -1)" 2 "# in an assignment's \${ } is no comment"
assert_eq "$(hook "$r" 'echo `echo #`; git push' | tail -1)" 2 "# inside backticks is no comment"
assert_eq "$(hook "$r" $'echo $[ 1 # ]\n>out git push' | tail -1)" 2 "# inside \$[ ] is no comment"
assert_eq "$(hook "$r" $'echo $[(1+(2))]; ((x<<y))\ngit push' | tail -1)" 2 ")) inside \$[ ] leaves the (( )) count alone"
# an ambiguous parse falls back to reading every line: no heredoc or comment hides a push (#9 review round 2)
assert_eq "$(hook "$r" $'echo ${x/<<EOF/}\ngit push' | tail -1)" 2 "<< inside \${ } hides nothing"
assert_eq "$(hook "$r" $'echo `echo <<EOF`\ngit push' | tail -1)" 2 "<< inside backticks hides nothing"
assert_eq "$(hook "$r" $'(( (1+(2)) <<x ))\ngit push' | tail -1)" 2 "inner )) does not close (( ))"
assert_eq "$(hook "$r" $'echo $(( (1+(2)) <<x ))\ngit push' | tail -1)" 2 "inner )) does not close \$(( ))"
assert_eq "$(hook "$r" $'(( (1+(2)) <<x ))\ngit push\nx' | tail -1)" 2 "a shift with a matching later line is still no heredoc"
assert_eq "$(hook "$r" 'echo ${x:-$(echo }) #}; git push' | tail -1)" 2 "} in \$( ) inside \${ } hides nothing"
assert_eq "$(hook "$r" 'echo ${x:-`echo }` #}; git push' | tail -1)" 2 "} in backticks inside \${ } hides nothing"
assert_eq "$(hook "$r" $'echo $(cat <<EOF\nhi\nEOF)\ngit push' | tail -1)" 2 "heredoc in \$( ) ending on EOF) hides nothing"
assert_eq "$(hook "$r" $'echo `cat <<EOF\nhi\nEOF`\ngit push' | tail -1)" 2 "heredoc in backticks ending on EOF\` hides nothing"
assert_eq "$(hook "$r" $'((cd .) ) # it\'s\ngit push' | tail -1)" 2 "an apostrophe after an unclosed (( hides nothing"
assert_eq "$(hook "$r" $'cat > notes <<EOF\ngit push origin main' | tail -1)" 2 "an unterminated heredoc hides nothing"
assert_eq "$(hook "$r" $'echo $(cat <<EOF\nit\'s\nEOF)\ngit push' | tail -1)" 2 "a quote in a heredoc body in \$( ) hides nothing"
assert_eq "$(hook "$r" $'echo `cat <<EOF\na"b\nEOF`\ngit push' | tail -1)" 2 "a quote in a heredoc body in backticks hides nothing"
assert_eq "$(hook "$r" $'echo "$(echo "it\'s")"\ngit push' | tail -1)" 2 "a quote nested in \"\$( )\" hides nothing"
assert_eq "$(hook "$d/fresh" 'git push origin HEAD')" 0 "plain push from a fresh cwd"
assert_eq "$(hook "$r" "cd $d/fresh && git push")" 0 "cd <fresh> && git push from a stale cwd"
assert_eq "$(hook "$r" 'cd ../fresh && git push')" 0 "relative cd resolves against the payload cwd"
assert_eq "$(hook "$d/fresh" "git -C $d/stale push")" 2 "git -C <stale> push from a fresh cwd"
assert_eq "$(hook "$r" 'git -C ../fresh push')" 0 "relative -C"
assert_eq "$(hook "$r" "git -C \"$d/fresh wt\" push")" 0 "quoted -C path with a space"
assert_eq "$(hook "$r" "cd '$d/fresh wt' && git push")" 0 "quoted cd path with a space"
assert_eq "$(hook "$d/fresh" 'git -c push.default=current push')" 0 "git -c k=v push, fresh"
assert_eq "$(hook "$d/fresh" "echo hi; git -c k=v -C $d/stale push origin HEAD")" 2 "-c and -C after ; in a chain"
assert_eq "$(hook "$d/fresh" "true && cd $d/stale && git push 2>&1 | tail -1")" 2 "cd mid-chain, piped push"
assert_eq "$(hook "$d/fresh" "git --git-dir=$r/.git push")" 2 "--git-dir= of the stale main checkout"
assert_eq "$(hook "$r" "git --git-dir $r/.git/worktrees/fresh push")" 0 "--git-dir <linked worktree gitdir>"
assert_eq "$(hook "$d/fresh" "git -C $d/fresh push && git -C $d/stale push")" 2 "every push in the chain is judged"
assert_eq "$(hook "$d/fresh" "bash -c 'cd $d/stale && git push'")" 2 "bash -c is read as a command"
assert_eq "$(hook "$plain" "git -C $d/stale push")" 2 "non-Orca cwd pushing into an Orca repo is gated"
assert_eq "$(hook "$r" "git -C $plain/p push")" 0 "push into a repo without config is left alone"
assert_eq "$(hook "$r" "git -C $d/stale status")" 0 "not a push"
assert_eq "$(hook "$r" 'echo git push')" 0 "git push as an argument is not a push"
assert_contains "$(hook_json Bash "$d/fresh" "git -C $d/stale push" | bash "$ORCA_SRC/hooks/pretool.sh" 2>&1)" "stale for $d/stale"
assert_eq "$(hook "$d/fresh" 'git merge stale')" 2 "merge still blocked"
